/**
 * Register Page
 */

import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import authService from '../services/authService';
import './Auth.css';

const Register = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: '',
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPasswordRequirements, setShowPasswordRequirements] = useState(false);
  const navigate = useNavigate();
  const { register } = useAuth();

  // Password validation rules
  const passwordRequirements = {
    minLength: formData.password.length >= 8,
    hasUppercase: /[A-Z]/.test(formData.password),
    hasLowercase: /[a-z]/.test(formData.password),
    hasNumber: /[0-9]/.test(formData.password),
    hasSpecialChar: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(formData.password),
  };

  const isPasswordValid = Object.values(passwordRequirements).every(req => req);
  const passwordsMatch = formData.password === formData.confirmPassword && formData.password.length > 0;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

    if (name === 'password') {
      setShowPasswordRequirements(true);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Client-side validation
    if (!isPasswordValid) {
      setError('Password does not meet all security requirements');
      return;
    }

    if (!passwordsMatch) {
      setError('Passwords do not match');
      return;
    }

    setLoading(true);

    try {
      const data = await authService.register(
        formData.fullName,
        formData.email,
        formData.password,
        formData.confirmPassword
      );
      register(data.user, data.token);
      navigate('/events');
    } catch (err) {
      const errorMsg = err.message || 'Registration failed';
      if (err.errors && Array.isArray(err.errors) && err.errors.length > 0) {
        setError(err.errors.join('\n'));
      } else {
        setError(errorMsg);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="auth-page">
      <div className="auth-container">
        <div className="auth-card">
          <h2>Create Account</h2>

          {error && <div className="error-message">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Full Name</label>
              <input
                type="text"
                name="fullName"
                value={formData.fullName}
                onChange={handleChange}
                placeholder="Enter your full name"
                required
              />
            </div>

            <div className="form-group">
              <label>Email Address</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                placeholder="Enter your email"
                required
              />
            </div>

            <div className="form-group">
              <label>Password</label>
              <input
                type="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                placeholder="Enter a strong password"
                onFocus={() => setShowPasswordRequirements(true)}
                onBlur={() => {
                  if (formData.password.length === 0) {
                    setShowPasswordRequirements(false);
                  }
                }}
                required
              />
              {showPasswordRequirements && formData.password.length > 0 && (
                <div style={{ marginTop: '10px', fontSize: '12px' }}>
                  <div style={{ color: passwordRequirements.minLength ? '#28a745' : '#dc3545', marginBottom: '5px' }}>
                    ✓ {passwordRequirements.minLength ? '✓' : '✗'} At least 8 characters
                  </div>
                  <div style={{ color: passwordRequirements.hasUppercase ? '#28a745' : '#dc3545', marginBottom: '5px' }}>
                    ✓ {passwordRequirements.hasUppercase ? '✓' : '✗'} Uppercase letter (A-Z)
                  </div>
                  <div style={{ color: passwordRequirements.hasLowercase ? '#28a745' : '#dc3545', marginBottom: '5px' }}>
                    ✓ {passwordRequirements.hasLowercase ? '✓' : '✗'} Lowercase letter (a-z)
                  </div>
                  <div style={{ color: passwordRequirements.hasNumber ? '#28a745' : '#dc3545', marginBottom: '5px' }}>
                    ✓ {passwordRequirements.hasNumber ? '✓' : '✗'} Number (0-9)
                  </div>
                  <div style={{ color: passwordRequirements.hasSpecialChar ? '#28a745' : '#dc3545' }}>
                    ✓ {passwordRequirements.hasSpecialChar ? '✓' : '✗'} Special character (!@#$%^&*)
                  </div>
                </div>
              )}
            </div>

            <div className="form-group">
              <label>Confirm Password</label>
              <input
                type="password"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                placeholder="Confirm your password"
                required
              />
              {formData.confirmPassword && (
                <div style={{ marginTop: '5px', fontSize: '12px', color: passwordsMatch ? '#28a745' : '#dc3545' }}>
                  {passwordsMatch ? '✓ Passwords match' : '✗ Passwords do not match'}
                </div>
              )}
            </div>

            <button 
              type="submit" 
              className="btn-submit" 
              disabled={loading || !isPasswordValid || !passwordsMatch}
              style={{
                opacity: (loading || !isPasswordValid || !passwordsMatch) ? 0.6 : 1,
                cursor: (loading || !isPasswordValid || !passwordsMatch) ? 'not-allowed' : 'pointer',
              }}
            >
              {loading ? 'Creating Account...' : 'Register'}
            </button>
          </form>

          <p className="auth-footer">
            Already have an account? <Link to="/login">Login here</Link>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Register;
